/**
 * Governed-package documentation projection.
 *
 * The canonical data lives in `data/packages/governed-packages.json`.
 * These documents are generated from it and must never be hand-edited.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import type { GovernedPackageRecord, PackageDriftFile } from "../src/domain/governed-package";
import { loadGovernedPackageFile, loadPackageDriftFile } from "../src/lib/governed-package-registry";

const OUT_DIR = join(process.cwd(), "docs", "packages");

const HEADER = (title: string) =>
  `# ${title}\n\n> Generated from \`data/packages/governed-packages.json\` by ` +
  `\`scripts/gen-governed-package-docs.ts\`. Do not edit by hand.\n> A package summarizes governed ` +
  `state. It is not a register, it carries no authority, and it closes nothing.\n`;

function table(rows: string[][], head: string[]): string {
  const line = (cells: string[]) => `| ${cells.join(" | ")} |`;
  return [line(head), line(head.map(() => "---")), ...rows.map(line)].join("\n");
}

function esc(value: string): string {
  return value.replace(/\|/g, "\\|");
}

function packageRegister(records: GovernedPackageRecord[], boundary: string): string {
  const sections = records.map((record) =>
    [
      `## ${record.package_id} — ${esc(record.title)} (${record.authority_role})`,
      "",
      table(
        [
          ["Version", record.version],
          ["State date", record.state_date],
          ["Authority role", record.authority_role],
          ["Canonical status", record.canonical_status],
          ["Predecessor", record.predecessor_package ?? "—"],
          ["Personal data", record.personal_data_state],
          ["Release", record.release_state],
          ["Evidence", record.evidence_references.join(", ") || "—"],
        ].map(([k, v]) => [k as string, esc(v as string)]),
        ["Field", "Value"],
      ),
      "",
      `**Relationship to the canonical registers.** ${esc(record.register_relationship)}`,
      "",
      "### Artifacts",
      "",
      table(
        record.artifacts.map((artifact) => [
          artifact.artifact_id,
          `\`${esc(artifact.filename)}\``,
          artifact.media_type,
          artifact.byte_size === null ? "—" : `${artifact.byte_size}`,
          artifact.retention_state,
          artifact.integrity_state,
        ]),
        ["ID", "Filename", "Media type", "Bytes", "Retention", "Integrity"],
      ),
      "",
    ].join("\n"),
  );

  return [HEADER("Governed reference package register"), "", "## Boundary", "", boundary, "", ...sections].join(
    "\n",
  );
}

function integrityManifest(records: GovernedPackageRecord[]): string {
  const rows = records.flatMap((record) =>
    record.artifacts.map((artifact) => [
      record.package_id,
      `\`${esc(artifact.filename)}\``,
      artifact.declared_sha256 ? `\`${artifact.declared_sha256}\`` : "not declared",
      artifact.sha256 ? `\`${artifact.sha256}\`` : "not measured",
      artifact.integrity_state,
    ]),
  );

  return [
    HEADER("Package integrity verification"),
    "",
    "Digests were recomputed by this program against the supplied files and compared with the",
    "digests printed in the supplied manifest. A verified match is a file-identity check only.",
    "It is not independent validation and says nothing about the accuracy of package contents.",
    "",
    table(rows, ["Package", "Filename", "Declared SHA-256", "Measured SHA-256", "State"]),
    "",
    "The v0.3.0 manifest declares no digest for itself, because hashing a file that contains its own",
    "digest is circular. Its measured digest above is a measurement by this program, not a manifest claim.",
    "",
  ].join("\n");
}

function completenessBoundary(records: GovernedPackageRecord[]): string {
  return [
    HEADER("Package completeness boundary"),
    "",
    ...records.flatMap((record) => [
      `## ${record.package_id} — v${record.version} (${record.authority_role})`,
      "",
      esc(record.completeness_boundary),
      "",
      "### Per-artifact limitations",
      "",
      ...record.artifacts.flatMap((artifact) => [
        `**${artifact.artifact_id} — \`${esc(artifact.filename)}\`**`,
        "",
        ...artifact.limitations.map((limitation) => `- ${esc(limitation)}`),
        "",
      ]),
    ]),
  ].join("\n");
}

function nonClaimBoundary(records: GovernedPackageRecord[]): string {
  return [
    HEADER("Package non-claim boundary"),
    "",
    "Inclusion in a package, file recency, a successful digest match, and a passing test are all",
    "independent of authority. None of them promotes a record, closes a finding, closes a work",
    "package, changes a gate, or authorizes a successor package.",
    "",
    ...records.flatMap((record) => [
      `## ${record.package_id} — v${record.version} (${record.authority_role})`,
      "",
      ...record.non_claims.map((claim) => `- ${esc(claim)}`),
      "",
    ]),
  ].join("\n");
}

function driftRegister(drift: PackageDriftFile): string {
  const lines: string[] = [
    "# v0.3.0 package reconciliation and drift register",
    "",
    `Generated from \`data/packages/package-drift.json\` (schema ${drift.schema_version}). Edit the register, not this file. Recorded as EV-034.`,
    "",
    drift.register_purpose,
    "",
    "## Reconciled — package agrees with the canonical record",
    "",
    "| Assertion in PKG-002 | Canonical locator | Result |",
    "| --- | --- | --- |",
    ...drift.reconciled.map(
      (row) => `| ${row.assertion} | ${row.canonical_locator} | ${row.result} |`,
    ),
    "",
    `## Drift — ${drift.drift.filter((row) => row.disposition === "UNRESOLVED").length} unresolved, recorded and not resolved`,
    "",
    "| ID | Item | Package locator | Repository locator | Controlling authority | Disposition | Note |",
    "| --- | --- | --- | --- | --- | --- | --- |",
    ...drift.drift.map(
      (row) =>
        `| ${row.drift_id} | ${row.item} | ${row.package_locator} | ${row.repository_locator} | ${row.controlling_authority} | ${row.disposition} | ${row.disposition_note} |`,
    ),
    "",
    "No drift row was resolved by this cycle. Resolving a drift row is an owner decision or a",
    "later executed validation, never an edit made to make the two planes agree.",
  ];
  return lines.join("\n");
}

function main(): void {
  const file = loadGovernedPackageFile();
  const drift = loadPackageDriftFile();
  mkdirSync(OUT_DIR, { recursive: true });

  const outputs: Array<[string, string]> = [
    ["PACKAGE_REGISTER.md", packageRegister(file.records, file.package_boundary)],
    ["INTEGRITY_MANIFEST.md", integrityManifest(file.records)],
    ["COMPLETENESS_BOUNDARY.md", completenessBoundary(file.records)],
    ["NON_CLAIM_BOUNDARY.md", nonClaimBoundary(file.records)],
    ["DRIFT_REGISTER.md", driftRegister(drift)],
  ];

  for (const [name, content] of outputs) {
    writeFileSync(join(OUT_DIR, name), content.endsWith("\n") ? content : `${content}\n`);
    console.log(`wrote docs/packages/${name}`);
  }
}

main();

/**
 * WP-007 documentation projection.
 *
 * The canonical data lives in `data/historical/historical-sources.json`.
 * These documents are generated from it and must never be hand-edited.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import type { HistoricalSourceRecord } from "../src/domain/historical-source";
import { loadHistoricalSourceFile } from "../src/lib/historical-source-registry";

const OUT_DIR = join(process.cwd(), "docs", "wp-007");

const HEADER = (title: string) =>
  `# ${title}\n\n> Generated from \`data/historical/historical-sources.json\` by ` +
  `\`scripts/gen-historical-source-docs.ts\`. Do not edit by hand.\n> No source is promoted into ` +
  `current authority by appearing here.\n`;

function table(rows: string[][], head: string[]): string {
  const line = (cells: string[]) => `| ${cells.join(" | ")} |`;
  return [line(head), line(head.map(() => "---")), ...rows.map(line)].join("\n");
}

function esc(value: string): string {
  return value.replace(/\|/g, "\\|");
}

function sourceUniverse(records: HistoricalSourceRecord[], boundary: string): string {
  return [
    HEADER("WP-007 source universe"),
    "",
    "## Boundary",
    "",
    boundary,
    "",
    "## Inventory",
    "",
    table(
      records.map((r) => [r.source_id, esc(r.title), r.source_family, `\`${esc(r.exact_locator)}\``]),
      ["ID", "Source", "Family", "Exact locator"],
    ),
    "",
  ].join("\n");
}

function classificationRegister(records: HistoricalSourceRecord[]): string {
  return [
    HEADER("WP-007 authority classification register"),
    "",
    table(
      records.map((r) => [
        r.source_id,
        r.authority_classification,
        r.promotion_state,
        esc(r.classification_basis),
        r.classification_evidence.join(", ") || "—",
      ]),
      ["ID", "Classification", "Promotion", "Basis", "Supporting records"],
    ),
    "",
    "Classification records how much authority a source carries now. Age, volume, and effort never",
    "upgrade it; only a recorded owner decision can.",
    "",
  ].join("\n");
}

function accessLimitations(records: HistoricalSourceRecord[]): string {
  return [
    HEADER("WP-007 access limitations"),
    "",
    table(
      records.map((r) => [
        r.source_id,
        r.access_limitation,
        r.immutability,
        r.pii_status,
        esc(r.access_note),
      ]),
      ["ID", "Access", "Immutability", "Personal data", "Note"],
    ),
    "",
    "Sources recorded `NOT-ACCESSIBLE-TO-EXECUTOR` carry no version, no hash, and no content claim.",
    "",
  ].join("\n");
}

function provenanceIndex(records: HistoricalSourceRecord[]): string {
  return [
    HEADER("WP-007 provenance index"),
    "",
    table(
      records.map((r) => [
        r.source_id,
        `\`${esc(r.version_or_hash)}\``,
        r.recovery_relevance,
        esc(r.recovery_relevance_reason),
        r.inventoried_on,
      ]),
      ["ID", "Version or hash", "Recovery relevance", "Reason", "Inventoried"],
    ),
    "",
  ].join("\n");
}

function refusedClaims(records: HistoricalSourceRecord[]): string {
  const refused = records.filter((r) => r.authority_classification === "REFUSED");
  return [
    HEADER("WP-007 refused claims"),
    "",
    "This register refuses, explicitly:",
    "",
    "- that any inventoried source has been read, verified, or reproduced;",
    "- that any historical source carries current authority by virtue of being recorded;",
    "- that the universe is complete beyond the declared boundary;",
    "- that unreachable sources contain, or do not contain, anything in particular;",
    "- that WP-039 exists, is authorized, or follows from WP-038;",
    "- that any gate, work package, or finding is closed by this cycle.",
    "",
    "## Sources refused as recovery inputs",
    "",
    refused.length === 0
      ? "None recorded."
      : table(
          refused.map((r) => [r.source_id, esc(r.title), esc(r.classification_basis)]),
          ["ID", "Source", "Basis for refusal"],
        ),
    "",
  ].join("\n");
}

function main() {
  const file = loadHistoricalSourceFile();
  const records = file.records;
  mkdirSync(OUT_DIR, { recursive: true });

  const outputs: [string, string][] = [
    ["SOURCE_UNIVERSE.md", sourceUniverse(records, file.universe_boundary)],
    ["CLASSIFICATION_REGISTER.md", classificationRegister(records)],
    ["ACCESS_LIMITATIONS.md", accessLimitations(records)],
    ["PROVENANCE_INDEX.md", provenanceIndex(records)],
    ["REFUSED_CLAIMS.md", refusedClaims(records)],
  ];

  for (const [name, body] of outputs) {
    writeFileSync(join(OUT_DIR, name), body, "utf8");
  }
  console.log(`WP-007: projected ${records.length} sources into ${outputs.length} documents.`);
}

main();

/**
 * Generates the WP-038 register projections from the canonical governance data
 * in `data/governance/`. The JSON files are the source of truth; these markdown
 * files are a projection and must never be hand edited.
 *
 * Run: bun run scripts/gen-obligation-docs.ts
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import {
  CONTROL_FAMILIES,
  OBLIGATION_DOMAINS,
  PROHIBITED_OBLIGATION_CLAIMS,
  isGap,
  type ObligationRecord,
} from "../src/domain/obligation";
import {
  loadAuthorities,
  loadObligationContext,
  loadObligations,
} from "../src/lib/obligation-registry";

const OUT = join(process.cwd(), "docs", "wp-038");
mkdirSync(OUT, { recursive: true });

const HEADER =
  "<!-- Generated by scripts/gen-obligation-docs.ts from data/governance/. Edit the data, not this file. -->\n\n";

const authorities = loadAuthorities();
const obligations = loadObligations();
const { conflicts, stale_references, data_triggers } = loadObligationContext();

function write(name: string, body: string) {
  writeFileSync(join(OUT, name), `${HEADER}${body.trimEnd()}\n`, "utf8");
}

const cell = (value: string) => value.replace(/\|/g, "/").replace(/\n/g, " ");

function table(headers: string[], rows: string[][]) {
  return [
    `| ${headers.join(" | ")} |`,
    `|${headers.map(() => "---").join("|")}|`,
    ...rows.map((row) => `| ${row.map(cell).join(" | ")} |`),
  ].join("\n");
}

const DOMAIN_TITLES: Record<string, string> = {
  "student-privacy": "Student privacy",
  accessibility: "Accessibility",
  security: "Security",
  "supply-chain": "Software supply chain",
  interoperability: "Interoperability",
  "ai-governance": "AI governance",
  "records-retention": "Records retention and deletion",
  procurement: "Procurement and attestation",
  "public-surface": "Public surface and claims",
};

function obligationDetail(record: ObligationRecord) {
  return [
    `### ${record.obligation_id} — ${record.title}`,
    "",
    table(
      ["Field", "Value"],
      [
        ["Source", `${record.source_authority} (${record.source_id})`],
        ["Authority type", record.source_type],
        ["Citation", record.citation],
        ["Locator", record.source_url],
        ["Source version", record.source_version],
        ["Verified on", record.verified_on],
        ["Jurisdiction", record.jurisdiction],
        ["Applicability", record.applicability_state],
        ["Trigger", record.applicability_trigger],
        ["Control family", record.control_family],
        ["Control status", record.control_status],
        ["Evidence status", record.evidence_status],
        ["Owning route", record.mapped_work_package],
        ["Review requirement", record.review_requirement ?? "none recorded"],
        ["Review trigger", record.review_trigger],
      ],
    ),
    "",
    `**What the source states.** ${record.source_statement_boundary}`,
    "",
    `**Obligation.** ${record.obligation_summary}`,
    "",
    `**SSLS interpretation.** ${record.ssls_interpretation}`,
    "",
    `**Current phase.** ${record.current_phase_applicability}`,
    "",
    `**Future phase.** ${record.future_phase_applicability}`,
    "",
    `**Required control.** ${record.required_control}`,
    "",
    `**Current control.** ${record.current_control}`,
    "",
    `**Evidence required.** ${record.evidence_requirement} Minimum method: ${record.minimum_evidence_method}`,
    "",
    `**Claim permitted.** ${record.claim_implication}`,
    "",
    `**Claim refused.** ${record.prohibited_claim}`,
    record.notes ? `\n**Note.** ${record.notes}` : "",
  ].join("\n");
}

// README
write(
  "README.md",
  `# WP-038 — Regulatory, Standards & Obligation Baseline

Authority class: candidate. Method: executor-produced, primary-source verified, not independent.
Executed under SSLS-BPP-001 v2.0 (DEC-007) and authorised by DEC-017, which authorises generation
and execution of WP-038 only.

This package records what external authorities require, whether each requirement applies to SSLS
today, what SSLS actually has, and what evidence would be needed. Those are four separate facts and
this package never collapses them into a compliance statement.

## Canonical data

| File | Contents |
|---|---|
| \`data/governance/OBLIGATION_SCHEMA.json\` | Schema for both registers |
| \`data/governance/external-authorities.json\` | ${authorities.length} verified external sources |
| \`data/governance/obligations.json\` | ${obligations.length} interpreted obligations |
| \`data/governance/obligation-context.json\` | Conflicts, stale references, data triggers |

Every document in this directory whose header says so is a projection of that data.

## Documents

| Document | Purpose |
|---|---|
| \`METHOD_AND_LIMITS.md\` | How sources were verified and what that verification cannot support |
| \`JURISDICTION_SCOPE.md\` | Which jurisdictions are in scope and why |
| \`EXTERNAL_AUTHORITY_REGISTER.md\` | The source register |
| \`OBLIGATION_REGISTER.md\` | The full obligation register |
| \`APPLICABILITY_MATRIX.md\` | Obligations by applicability state |
| \`GAP_REGISTER.md\` | Where a required control is absent, partial or specified only |
| \`CONTROL_FAMILY_MAP.md\` | Obligations grouped by control family |
| \`EVIDENCE_REQUIREMENTS.md\` | What evidence each obligation would need |
| \`REVIEW_TRIGGERS.md\` | What event forces a review, and which need qualified review |
| \`CONFLICT_REGISTER.md\` | Source conflicts and ambiguities |
| \`STALE_REFERENCE_REGISTER.md\` | Project references checked against verified current sources |
| \`DATA_TRIGGER_MAP.md\` | Data classes and the obligations each would activate |
| \`REFUSED_CLAIMS.md\` | Wording this baseline will not produce |
| \`CLAIMS_RECONCILIATION.md\` | Claims Register reconciliation |
| \`DEC-012-BRIEF.md\` | Decision brief prepared for the owner |
| \`EXIT_CRITERIA_MATRIX.md\` | Exit criteria and their state |
| \`CLOSURE_RECOMMENDATION.md\` | Recommendation, with limitations preserved |
| \`HANDOFF_TO_WP-007.md\` | What carries forward |
${OBLIGATION_DOMAINS.map((d) => `| \`domain-${d}.md\` | ${DOMAIN_TITLES[d]} obligations |`).join("\n")}

## Boundaries

- No obligation in this register is recorded as met, satisfied or complied with.
- Applicability is not compliance. NOT-APPLICABLE means the trigger has not occurred.
- No product feature, database, live integration, AI feature or personal data was added.
- Only a recorded owner decision closes a gate.
`,
);

// Source register
write(
  "EXTERNAL_AUTHORITY_REGISTER.md",
  `# External authority register

${authorities.length} sources, each verified on ${authorities[0]?.verified_on ?? "n/a"} by direct retrieval from the issuing body or an official mirror.

Source status values: VERIFIED-CURRENT, VERIFIED-HISTORICAL, SUPERSEDED, UNVERIFIED, CONFLICTED.
A source recorded UNVERIFIED or CONFLICTED may not be used to support a determination.

${table(
  ["ID", "Title", "Type", "Citation", "Version", "Jurisdiction", "Status", "Lifecycle"],
  authorities.map((r) => [
    r.source_id,
    r.title,
    r.source_type,
    r.citation,
    r.source_version,
    r.jurisdiction,
    r.source_status,
    r.lifecycle,
  ]),
)}

## Source detail

${authorities
  .map((r) =>
    [
      `### ${r.source_id} — ${r.title}`,
      "",
      `- Issuing body: ${r.issuing_body}`,
      `- Authority type: ${r.source_type}`,
      `- Citation: ${r.citation}`,
      `- Locator: ${r.source_url}`,
      `- Version: ${r.source_version}; effective ${r.source_effective_date}`,
      `- Verified: ${r.verified_on} by ${r.verification_method}`,
      `- Status: ${r.source_status}; lifecycle ${r.lifecycle}`,
      `- Locators used: ${r.section_locators.join("; ")}`,
      "",
      `**What the source states.** ${r.source_statement}`,
      "",
      `**Reproduction boundary.** ${r.reproduction_boundary}`,
      r.notes ? `\n**Note.** ${r.notes}` : "",
    ].join("\n"),
  )
  .join("\n\n")}
`,
);

// Obligation register
write(
  "OBLIGATION_REGISTER.md",
  `# Obligation register

${obligations.length} obligations derived from the source register. Each record separates what the
source states from how SSLS reads it, and separates applicability from control status from evidence
status.

${table(
  ["ID", "Title", "Source", "Applicability", "Control", "Evidence", "Family"],
  obligations.map((r) => [
    r.obligation_id,
    r.title,
    r.source_id,
    r.applicability_state,
    r.control_status,
    r.evidence_status,
    r.control_family,
  ]),
)}

## Obligation detail

${obligations.map(obligationDetail).join("\n\n---\n\n")}
`,
);

// Domain files
for (const domain of OBLIGATION_DOMAINS) {
  const scoped = obligations.filter((r) => r.domain === domain);
  write(
    `domain-${domain}.md`,
    `# ${DOMAIN_TITLES[domain]}

${scoped.length} obligation${scoped.length === 1 ? "" : "s"} in this domain.

${
  scoped.length === 0
    ? "No obligations recorded in this domain."
    : table(
        ["ID", "Title", "Source", "Applicability", "Control status"],
        scoped.map((r) => [
          r.obligation_id,
          r.title,
          r.citation,
          r.applicability_state,
          r.control_status,
        ]),
      )
}

${scoped.map(obligationDetail).join("\n\n---\n\n")}
`,
  );
}

// Applicability matrix
const APPLICABILITY_MEANING: Record<string, string> = {
  "APPLIES-NOW": "The trigger has occurred. The obligation is live for the current build.",
  "APPLIES-AT-PILOT": "Attaches at the first district relationship or real data exchange.",
  "APPLIES-AT-LAUNCH": "Attaches when a hosted service is offered commercially.",
  CONDITIONAL: "Attaches only if a specific capability or data class is introduced.",
  REFERENCE: "Informs design. Creates no obligation on its own.",
  "NOT-APPLICABLE": "The trigger cannot occur in the current or planned scope.",
  UNKNOWN: "Applicability was not determined and must not be assumed either way.",
};

write(
  "APPLICABILITY_MATRIX.md",
  `# Applicability matrix

Applicability answers one question only: has the trigger occurred? It never answers whether SSLS
satisfies the obligation. NOT-APPLICABLE is not a pass.

${Object.entries(APPLICABILITY_MEANING)
  .map(([state, meaning]) => {
    const scoped = obligations.filter((r) => r.applicability_state === state);
    return [
      `## ${state} (${scoped.length})`,
      "",
      meaning,
      "",
      scoped.length === 0
        ? "None recorded."
        : table(
            ["ID", "Title", "Trigger", "Control status"],
            scoped.map((r) => [
              r.obligation_id,
              r.title,
              r.applicability_trigger,
              r.control_status,
            ]),
          ),
    ].join("\n");
  })
  .join("\n\n")}
`,
);

// Gap register
const gaps = obligations.filter(isGap);
write(
  "GAP_REGISTER.md",
  `# Gap register

A gap is an obligation that could attach and whose required control is missing, partial, specified
only, or unknown. Gaps are recorded, not remediated, in this work package.

${gaps.length} gaps recorded.

${table(
  ["ID", "Title", "Applicability", "Control status", "Required control", "Owning route"],
  gaps.map((r) => [
    r.obligation_id,
    r.title,
    r.applicability_state,
    r.control_status,
    r.required_control,
    r.mapped_work_package,
  ]),
)}

## Gaps whose trigger is nearest

${gaps
  .filter((r) => r.applicability_state === "APPLIES-NOW" || r.applicability_state === "CONDITIONAL")
  .map((r) => `- **${r.obligation_id}** ${r.title}. Trigger: ${r.applicability_trigger}`)
  .join("\n")}
`,
);

// Control family map
write(
  "CONTROL_FAMILY_MAP.md",
  `# Control family map

Obligations grouped by the SSLS control family that would satisfy them. Different sources using
different vocabulary map to the same family rather than creating a new one.

${CONTROL_FAMILIES.map((family) => {
  const scoped = obligations.filter((r) => r.control_family === family);
  if (scoped.length === 0) return null;
  return [
    `## ${family} (${scoped.length})`,
    "",
    table(
      ["ID", "Obligation", "Source", "Control status"],
      scoped.map((r) => [r.obligation_id, r.title, r.source_id, r.control_status]),
    ),
  ].join("\n");
})
  .filter(Boolean)
  .join("\n\n")}

## Families with no recorded obligation

${CONTROL_FAMILIES.filter((f) => !obligations.some((r) => r.control_family === f))
  .map((f) => `- ${f}`)
  .join("\n")}
`,
);

// Evidence requirements
write(
  "EVIDENCE_REQUIREMENTS.md",
  `# Evidence requirements

