  onChange: (next: Partial<CapabilitySearch>) => void;
}) {
  return (
    <section aria-labelledby="capability-filters-heading" className="mt-4">
      <h2 id="capability-filters-heading" className="font-display text-lg font-semibold">
        Filters
      </h2>
      <div className="mt-3 grid gap-3 rounded-md border border-border bg-surface p-3 sm:grid-cols-2 lg:grid-cols-3">
        <div className="flex flex-col gap-1">
          <label htmlFor="capability-search" className="text-xs font-semibold">
            Text search
          </label>
          <input
            id="capability-search"
            type="search"
            value={search.q}
            onChange={(event) => onChange({ q: event.target.value })}
            placeholder="Name, purpose, risk, owner"
            className="min-h-11 rounded-sm border border-border-strong bg-surface px-2 py-1 text-sm placeholder:text-muted-foreground"
          />
        </div>
        <FilterSelect
          id="capability-domain"
          label="Domain"
          value={search.domain}
          options={CAPABILITY_DOMAINS}
          optionLabel={(option) => `${option} — ${CAPABILITY_DOMAIN_META[option].name}`}
          onChange={(value) => onChange({ domain: value as CapabilitySearch["domain"] })}
        />
        <FilterSelect
          id="capability-type"
          label="Capability type"
          value={search.type}
          options={CAPABILITY_TYPES}
          optionLabel={(option) => CAPABILITY_TYPE_LABEL[option]}
          onChange={(value) => onChange({ type: value as CapabilitySearch["type"] })}
        />
        <FilterSelect
          id="capability-stage"
          label="Required to execute by stage"
          value={search.stage}
          options={SCALE_STAGES}
          optionLabel={(option) => `${option} — ${SCALE_STAGE_LABEL[option]}`}
          onChange={(value) => onChange({ stage: value as CapabilitySearch["stage"] })}
        />
        <FilterSelect
          id="capability-gate"
          label="Trigger gate"
          value={search.gate}
          options={TRIGGER_GATES}
          optionLabel={(option) => TRIGGER_GATE_META[option].label}
          onChange={(value) => onChange({ gate: value as CapabilitySearch["gate"] })}
        />
        <FilterSelect
          id="capability-independence"
          label="Independence"
          value={search.independence}
          options={INDEPENDENCE_LEVELS}
          optionLabel={(option) => INDEPENDENCE_LABEL[option]}
          onChange={(value) => onChange({ independence: value as CapabilitySearch["independence"] })}
        />
        <FilterSelect
          id="capability-maturity"
          label="Declared current maturity"
          value={search.maturity}
          options={MATURITY_LEVELS}
          optionLabel={(option) => MATURITY_LEVEL_LABEL[option]}
          onChange={(value) => onChange({ maturity: value as CapabilitySearch["maturity"] })}
        />
        <div className="flex items-end">
          <Link
            to="/capabilities"
            search={{ ...DEFAULT_CAPABILITY_SEARCH, view: search.view }}
            className="inline-flex min-h-11 items-center rounded-sm border border-border-strong px-3 text-sm font-semibold"
          >
            Clear all filters
          </Link>
        </div>
      </div>
      <p aria-live="polite" className="mt-2 text-sm font-semibold">
        {resultCount} capability records match the current filters.
      </p>
    </section>
  );
}

/* ------------------------------------------------------------------- chips */

const CHIP = "inline-flex items-center gap-1 rounded-sm border px-2 py-0.5 text-xs font-semibold";

export function StageChip({ stage }: { stage: ScaleStage }) {
  return (
    <span className={`${CHIP} border-border-strong bg-muted`}>
      <span aria-hidden="true">[{stage}]</span>
      <span>{SCALE_STAGE_LABEL[stage]}</span>
      <span className="sr-only">Stage {stage}</span>
    </span>
  );
}

export function GateChip({ gate }: { gate: TriggerGate }) {
  const meta = TRIGGER_GATE_META[gate];
  return (
    <span className={`${CHIP} border-border-strong bg-muted`}>
      <span aria-hidden="true">{meta.marker}</span>
      <span>{meta.label}</span>
    </span>
  );
}

export function IndependenceChip({ level }: { level: IndependenceLevel }) {
  return (
    <span className={`${CHIP} border-border-strong bg-muted`}>
      <span aria-hidden="true">{INDEPENDENCE_MARKER[level]}</span>
      <span>{INDEPENDENCE_LABEL[level]}</span>
    </span>
  );
}

/* ------------------------------------------------------- search validation */

function option<T extends string>(value: unknown, allowed: readonly T[]): T | "all" {
  return typeof value === "string" && (allowed as readonly string[]).includes(value)
    ? (value as T)
    : "all";
}

/** Shared search parser so filters survive navigation into a detail page. */
export function parseCapabilitySearch(search: Record<string, unknown>): CapabilitySearch {
  const view = CAPABILITY_VIEWS.map((v) => v.id).includes(search["view"] as CapabilityView)
    ? (search["view"] as CapabilityView)
    : "registry";
  return {
    view,
    domain: option<CapabilityDomainId>(search["domain"], CAPABILITY_DOMAINS),
    type: option<CapabilityType>(search["type"], CAPABILITY_TYPES),
    stage: option<ScaleStage>(search["stage"], SCALE_STAGES),
    gate: option<TriggerGate>(search["gate"], TRIGGER_GATES),
    independence: option<IndependenceLevel>(search["independence"], INDEPENDENCE_LEVELS),
    maturity: option<MaturityLevel>(search["maturity"], MATURITY_LEVELS),
    q: typeof search["q"] === "string" ? (search["q"] as string) : "",
  };
}

import { Link } from "@tanstack/react-router";
import {
  CONFORMANCE_STATUS_LABEL,
  TEMPLATE_MATURITY_META,
  VALIDATION_RESULT_LABEL,
  type ConformanceStatus,
  type TemplateMaturity,
  type ValidationResult,
} from "@/domain";

export const DESIGN_SYSTEM_VIEWS = [
  { id: "overview", label: "Overview" },
  { id: "tokens", label: "Tokens" },
  { id: "typography", label: "Typography" },
  { id: "grid", label: "Grid and coordinates" },
  { id: "assets", label: "Brand assets" },
  { id: "templates", label: "Interface templates" },
  { id: "workspaces", label: "Workspace templates" },
  { id: "families", label: "Experience families" },
  { id: "blueprints", label: "Blueprints" },
  { id: "states", label: "States" },
  { id: "motion", label: "Motion and responsive" },
  { id: "accessibility", label: "Accessibility" },
  { id: "conformance", label: "Conformance" },
] as const;

export type DesignSystemView = (typeof DESIGN_SYSTEM_VIEWS)[number]["id"];

export interface DesignSystemSearch {
  view: DesignSystemView;
  maturity: TemplateMaturity | "all";
  q: string;
}

export const DEFAULT_DESIGN_SYSTEM_SEARCH: DesignSystemSearch = {
  view: "overview",
  maturity: "all",
  q: "",
};

const VIEW_IDS = DESIGN_SYSTEM_VIEWS.map((view) => view.id) as readonly string[];

export function parseDesignSystemSearch(input: Record<string, unknown>): DesignSystemSearch {
  const rawView = input["view"];
  const rawMaturity = input["maturity"];
  const rawQuery = input["q"];
  const view =
    typeof rawView === "string" && VIEW_IDS.includes(rawView) ? (rawView as DesignSystemView) : "overview";
  const maturity =
    typeof rawMaturity === "string" && rawMaturity in TEMPLATE_MATURITY_META
      ? (rawMaturity as TemplateMaturity)
      : "all";
  const q = typeof rawQuery === "string" ? rawQuery : "";
  return { view, maturity, q };
}


/** Views are links, so each one is addressable and survives a detour into detail. */
export function DesignSystemViewTabs({
  current,
  search,
}: {
  current: DesignSystemView;
  search: DesignSystemSearch;
}) {
  return (
    <nav aria-label="Design system views" className="mt-6">
      <ul className="flex flex-wrap gap-2">
        {DESIGN_SYSTEM_VIEWS.map((view) => {
          const isCurrent = view.id === current;
          return (
            <li key={view.id}>
              <Link
                to="/design-system"
                search={{ ...search, view: view.id }}
                aria-current={isCurrent ? "page" : undefined}
                className={
                  isCurrent
                    ? "inline-flex min-h-11 items-center rounded-sm border-2 border-border-strong bg-muted px-3 py-1.5 text-sm font-semibold underline underline-offset-4"
                    : "inline-flex min-h-11 items-center rounded-sm border border-border px-3 py-1.5 text-sm hover:bg-muted"
                }
              >
                {view.label}
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

/** Maturity is declared. The marker text carries the meaning, not the border. */
export function MaturityChip({ maturity }: { maturity: TemplateMaturity }) {
  const meta = TEMPLATE_MATURITY_META[maturity];
  return (
    <span
      data-maturity={maturity}
      title={meta.definition}
      className="inline-flex min-h-6 items-center gap-1.5 rounded-sm border border-border-strong bg-surface px-2 py-0.5 text-xs font-semibold"
    >
      <span aria-hidden="true" className="font-mono text-[0.65rem]">
        {meta.marker}
      </span>
      <span>{meta.label}</span>
    </span>
  );
}

export function ConformanceChip({ status }: { status: ConformanceStatus }) {
  const shape = status === "met" ? "[=]" : status === "not-met" ? "[x]" : "[?]";
  return (
    <span
      data-conformance={status}
      className="inline-flex min-h-6 items-center gap-1.5 rounded-sm border border-border-strong bg-surface px-2 py-0.5 text-xs font-semibold"
    >
      <span aria-hidden="true" className="font-mono text-[0.65rem]">
        {shape}
      </span>
      <span>{CONFORMANCE_STATUS_LABEL[status]}</span>
    </span>
  );
}

export function ValidationChip({ result }: { result: ValidationResult }) {
  const shape = result === "pass" ? "[=]" : result === "fail" ? "[x]" : "[ ]";
  return (
    <span
      data-validation={result}
      className="inline-flex min-h-6 items-center gap-1.5 rounded-sm border border-border-strong bg-surface px-2 py-0.5 text-xs font-semibold"
    >
      <span aria-hidden="true" className="font-mono text-[0.65rem]">
        {shape}
      </span>
      <span>{VALIDATION_RESULT_LABEL[result]}</span>
    </span>
  );
}

