import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

/**
 * Standard page frame. Every route renders exactly one H1 through this
 * component, which keeps heading structure consistent across the workspace.
 */
export function PageHeader({
  title,
  summary,
  children,
}: {
  title: string;
  summary: string;
  children?: ReactNode;
}) {
  return (
    // A plain container, not <header>: the page banner landmark belongs to the
    // application shell, and a second banner would create landmark ambiguity.
    <div className="border-b border-border pb-5">
      <h1 className="font-display text-2xl leading-tight font-bold sm:text-3xl">{title}</h1>
      <p className="measure mt-2 text-base text-muted-foreground">{summary}</p>
      {children ? <div className="mt-4">{children}</div> : null}
    </div>

  );
}

export function Section({
  title,
  description,
  children,
  className,
  id,
}: {
  title: string;
  description?: string;
  children: ReactNode;
  className?: string;
  id?: string;
}) {
  return (
    <section id={id} aria-labelledby={id ? `${id}-heading` : undefined} className={cn("mt-8", className)}>
      <h2 id={id ? `${id}-heading` : undefined} className="font-display text-xl font-semibold">
        {title}
      </h2>
      {description ? (
        <p className="measure mt-1 text-sm text-muted-foreground">{description}</p>
      ) : null}
      <div className="mt-4">{children}</div>
    </section>
  );
}

/**
 * Registry table wrapper. Tables scroll horizontally on narrow viewports rather
 * than truncating cell text, so essential content is never cut off.
 */
export function RegistryTable({
  caption,
  headers,
  children,
}: {
  caption: string;
  headers: string[];
  children: ReactNode;
}) {
  return (
    // `relative` matters: visually hidden text inside wide cells is absolutely
    // positioned, and without a positioned ancestor it escapes this scroll
    // container and pushes the whole page into horizontal scroll at 200% zoom.
    <div
      tabIndex={0}
      role="group"
      aria-label={caption}
      className="relative w-full min-w-0 max-w-full overflow-x-auto rounded-md border border-border bg-surface"
    >
      <table className="w-full min-w-[48rem] border-collapse text-left text-sm">
        <caption className="sr-only">{caption}</caption>
        <thead>
          <tr className="border-b border-border-strong bg-muted">
            {headers.map((header) => (
              <th key={header} scope="col" className="px-3 py-2 align-bottom font-semibold">
                {header}
              </th>
            ))}
          </tr>
        </thead>
        <tbody>{children}</tbody>
      </table>
    </div>
  );
}

export function Cell({ children, className }: { children: ReactNode; className?: string }) {
