/**
 * WP-007 — Historical Requirement Conformance Recovery.
 *
 * Canonical vocabulary and validation for the historical-source universe.
 * The canonical DATA lives in `data/historical/historical-sources.json`;
 * this module supplies the types and the deterministic checks that guard it.
 *
 * Nothing here promotes a historical source into current authority. A record
 * states where a source is, what it is, how much of it can be reached, and
 * whether it is worth reading during requirement recovery. Those are
 * independent facts and are never collapsed into one.
 */

/** What kind of thing the source is. */
export const HISTORICAL_SOURCE_FAMILIES = [
  "repository",
  "governance-document",
  "machine-register",
  "application-register",
  "bootstrap-artifact",
  "external-drive-folder",
  "chat-history",
  "external-service",
] as const;
export type HistoricalSourceFamily = (typeof HISTORICAL_SOURCE_FAMILIES)[number];

/**
 * How much authority the source carries RIGHT NOW. Age, volume, and effort do
 * not upgrade a classification; only a recorded owner decision can.
 */
export const AUTHORITY_CLASSIFICATIONS = [
  "CURRENT-AUTHORITY",
  "HISTORICAL-EVIDENCE",
  "RESEARCH-INPUT",
  "REFERENCE-ONLY",
  "REFUSED",
] as const;
export type HistoricalAuthorityClassification = (typeof AUTHORITY_CLASSIFICATIONS)[number];

/** What the executor can actually reach in this environment. */
export const ACCESS_LIMITATIONS = [
  "FULL",
  "READ-ONLY",
  "PARTIAL",
  "NOT-ACCESSIBLE-TO-EXECUTOR",
  "UNKNOWN",
] as const;
export type AccessLimitation = (typeof ACCESS_LIMITATIONS)[number];

/** Whether this program may edit the source. */
export const IMMUTABILITY_STATES = ["IMMUTABLE", "APPEND-ONLY", "MUTABLE"] as const;
export type ImmutabilityState = (typeof IMMUTABILITY_STATES)[number];

/** Expected usefulness for later requirement extraction. Not a promise to extract. */
export const RECOVERY_RELEVANCE = ["HIGH", "MEDIUM", "LOW", "NONE", "UNKNOWN"] as const;
export type RecoveryRelevance = (typeof RECOVERY_RELEVANCE)[number];

/**
 * Promotion state. Only `CURRENT-AUTHORITY` sources may read `PROMOTED`, and
 * that classification is itself carried by a recorded decision, not by WP-007.
 */
export const PROMOTION_STATES = ["NOT-PROMOTED", "PROMOTED-BY-DECISION"] as const;
export type PromotionState = (typeof PROMOTION_STATES)[number];

export const PII_STATUSES = [
  "NO-REAL-PII-ASSERTED",
  "UNINSPECTED",
  "REAL-PII-SUSPECTED",
  "REAL-PII-CONFIRMED",
] as const;
export type HistoricalPiiStatus = (typeof PII_STATUSES)[number];

export interface HistoricalSourceRecord {
  source_id: string;
  title: string;
  source_family: HistoricalSourceFamily;
  /** Repository path, absolute URL, or commit-bound reference. Never a description. */
  exact_locator: string;
  /** Commit SHA, content hash, declared version, or NOT-AVAILABLE. */
  version_or_hash: string;
  authority_classification: HistoricalAuthorityClassification;
  /** Why the classification is what it is, in plain language. */
  classification_basis: string;
  /** Decision or evidence identifiers supporting the classification. May be empty. */
  classification_evidence: string[];
  access_limitation: AccessLimitation;
  /** What specifically cannot be reached, or "None recorded." */
  access_note: string;
  immutability: ImmutabilityState;
  recovery_relevance: RecoveryRelevance;
  recovery_relevance_reason: string;
  promotion_state: PromotionState;
  pii_status: HistoricalPiiStatus;
  inventoried_on: string;
  /** What this record explicitly does not assert. */
  boundary: string;
}

/** Language that may never appear in a historical-source record. */
export const PROHIBITED_HISTORICAL_CLAIMS = [
  "compliant",
  "compliance verified",
  "certified",
  "conformant",
  "approved for release",
  "validated by",
  "production ready",
  "district approved",
] as const;

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

function has<T extends readonly string[]>(list: T, value: string): boolean {
  return (list as readonly string[]).includes(value);
}

/**
 * Deterministic record validation. Returns a list of human-readable problems;
 * an empty list means the record satisfies the schema rules.
 */
export function validateHistoricalSource(record: HistoricalSourceRecord): string[] {
  const issues: string[] = [];
  const id = record.source_id || "(missing id)";

  if (!/^HS-\d{3}$/.test(record.source_id)) issues.push(`${id}: source_id must match HS-000.`);
  if (!record.title.trim()) issues.push(`${id}: title is required.`);
  if (!has(HISTORICAL_SOURCE_FAMILIES, record.source_family))
    issues.push(`${id}: unknown source_family ${record.source_family}.`);
  if (!record.exact_locator.trim()) issues.push(`${id}: exact_locator is required.`);
  if (!record.version_or_hash.trim()) issues.push(`${id}: version_or_hash is required.`);
  if (!has(AUTHORITY_CLASSIFICATIONS, record.authority_classification))
    issues.push(`${id}: unknown authority_classification.`);
  if (!record.classification_basis.trim()) issues.push(`${id}: classification_basis is required.`);
  if (!has(ACCESS_LIMITATIONS, record.access_limitation))
    issues.push(`${id}: unknown access_limitation.`);
  if (!record.access_note.trim()) issues.push(`${id}: access_note is required.`);
  if (!has(IMMUTABILITY_STATES, record.immutability)) issues.push(`${id}: unknown immutability.`);
  if (!has(RECOVERY_RELEVANCE, record.recovery_relevance))
    issues.push(`${id}: unknown recovery_relevance.`);
  if (!record.recovery_relevance_reason.trim())
    issues.push(`${id}: recovery_relevance_reason is required.`);
  if (!has(PROMOTION_STATES, record.promotion_state)) issues.push(`${id}: unknown promotion_state.`);
  if (!has(PII_STATUSES, record.pii_status)) issues.push(`${id}: unknown pii_status.`);
  if (!ISO_DATE.test(record.inventoried_on)) issues.push(`${id}: inventoried_on must be ISO date.`);
  if (!record.boundary.trim()) issues.push(`${id}: boundary is required.`);

  if (record.authority_classification !== "CURRENT-AUTHORITY" && record.promotion_state !== "NOT-PROMOTED")
    issues.push(`${id}: only a CURRENT-AUTHORITY source may carry a promoted state.`);

  if (record.version_or_hash === "NOT-AVAILABLE" && record.access_limitation === "FULL")
    issues.push(`${id}: a fully accessible source must carry a version or hash.`);

  if (
    record.access_limitation === "NOT-ACCESSIBLE-TO-EXECUTOR" &&
    record.recovery_relevance !== "UNKNOWN"
  )
    issues.push(`${id}: an unreachable source cannot carry a known recovery relevance.`);

  if (record.pii_status === "REAL-PII-CONFIRMED" || record.pii_status === "REAL-PII-SUSPECTED")
    issues.push(`${id}: real PII may not be inventoried under the current boundary.`);

  const haystack = [
    record.title,
    record.classification_basis,
    record.recovery_relevance_reason,
    record.access_note,
    record.boundary,
  ]
    .join(" ")
    .toLowerCase();
  for (const phrase of PROHIBITED_HISTORICAL_CLAIMS) {
    if (haystack.includes(phrase)) issues.push(`${id}: prohibited claim language "${phrase}".`);
  }

  return issues;
}

/** A source that must be read before requirement extraction can be considered complete. */
export function isRecoveryCritical(record: HistoricalSourceRecord): boolean {
  return record.recovery_relevance === "HIGH" && record.access_limitation !== "NOT-ACCESSIBLE-TO-EXECUTOR";
}

fix.text:
/\blegally required\b|\brequired by law\b|\bmandated by law\b/i.test(
  record.obligation_summary,
)

source:
/**
 * WP-038 — Regulatory, Standards & Obligation Baseline.
 *
 * Canonical vocabularies and validation for the external-authority source
 * register and the obligation register. The canonical DATA lives in
 * `data/governance/external-authorities.json` and
 * `data/governance/obligations.json`; this module supplies the types and the
 * deterministic checks that guard them.
 *
 * Nothing here asserts compliance. An obligation record states what a source
 * requires, whether it applies to SSLS yet, and what SSLS actually has. Those
 * are four independent facts and are never collapsed into one.
 */

/** How much authority a source actually carries. Adoption never upgrades it. */
export const SOURCE_AUTHORITY_TYPES = [
  "statute",
  "regulation",
  "official-guidance",
  "standard",
  "voluntary-framework",
  "attestation-standard",
  "procurement-expectation",
  "market-expectation",
  "contractual",
  "internal-policy",
] as const;
export type SourceAuthorityType = (typeof SOURCE_AUTHORITY_TYPES)[number];

/** Authority types that can, on their own, legally require something. */
export const LEGALLY_BINDING_AUTHORITY_TYPES: readonly SourceAuthorityType[] = [
  "statute",
  "regulation",
];

/** Verification state of the source text itself, not of SSLS. */
export const SOURCE_STATUSES = [
  "VERIFIED-CURRENT",
  "VERIFIED-HISTORICAL",
  "SUPERSEDED",
  "UNVERIFIED",
  "CONFLICTED",
] as const;
export type SourceStatus = (typeof SOURCE_STATUSES)[number];

/** Legislative/regulatory lifecycle. Proposed is never effective. */
export const SOURCE_LIFECYCLES = [
  "EFFECTIVE",
  "ADOPTED-NOT-YET-EFFECTIVE",
  "PROPOSED-PENDING",
  "WITHDRAWN",
  "NOT-APPLICABLE",
  "UNKNOWN",
] as const;
export type SourceLifecycle = (typeof SOURCE_LIFECYCLES)[number];

export const JURISDICTIONS = [
  "US-FEDERAL",
  "US-MA",
  "US-STATE-OTHER",
  "US-LOCAL-DISTRICT",
  "INTERNATIONAL",
  "NOT-JURISDICTIONAL",
] as const;
export type Jurisdiction = (typeof JURISDICTIONS)[number];

export const APPLICABILITY_STATES = [
  "APPLIES-NOW",
  "APPLIES-AT-PILOT",
  "APPLIES-AT-LAUNCH",
  "CONDITIONAL",
  "REFERENCE",
  "NOT-APPLICABLE",
  "UNKNOWN",
] as const;
export type ObligationApplicability = (typeof APPLICABILITY_STATES)[number];

export const CONTROL_STATUSES = [
  "IMPLEMENTED",
  "PARTIAL",
  "SPECIFICATION-ONLY",
  "MISSING",
  "DEFERRED",
  "NOT-APPLICABLE",
  "UNKNOWN",
] as const;
export type ControlStatus = (typeof CONTROL_STATUSES)[number];

export const OBLIGATION_EVIDENCE_STATUSES = [
  "CURRENT",
  "STALE",
  "EXPIRED",
  "SUPERSEDED",
  "INAPPLICABLE",
  "UNKNOWN",
  "NOT-PRODUCED",
] as const;
export type ObligationEvidenceStatus = (typeof OBLIGATION_EVIDENCE_STATUSES)[number];

/** The smallest coherent SSLS control families. Terminology differences do not create new ones. */
export const CONTROL_FAMILIES = [
  "GOVERNANCE",
  "PRIVACY",
  "IDENTITY & ACCESS",
  "DATA MINIMIZATION",
  "RETENTION & DELETION",
  "ACCESSIBILITY",
  "SECURITY",
  "VULNERABILITY MANAGEMENT",
  "SOFTWARE SUPPLY CHAIN",
  "INCIDENT RESPONSE",
  "BUSINESS CONTINUITY",
  "VENDOR MANAGEMENT",
  "INTEROPERABILITY",
  "AI GOVERNANCE",
  "CLAIMS / TRANSPARENCY",
  "EDUCATIONAL VALIDITY",
  "HUMAN REVIEW",
] as const;
export type ControlFamily = (typeof CONTROL_FAMILIES)[number];

export const REVIEW_REQUIREMENTS = [
  "LEGAL REVIEW REQUIRED",
  "PRIVACY REVIEW REQUIRED",
  "SECURITY REVIEW REQUIRED",
  "ACCESSIBILITY REVIEW REQUIRED",
  "PROCUREMENT REVIEW REQUIRED",
  "EDUCATION POLICY REVIEW REQUIRED",
] as const;
export type ReviewRequirement = (typeof REVIEW_REQUIREMENTS)[number];

export const OBLIGATION_DOMAINS = [
  "student-privacy",
  "accessibility",
  "security",
  "supply-chain",
  "interoperability",
  "ai-governance",
  "records-retention",
  "procurement",
  "public-surface",
] as const;
export type ObligationDomain = (typeof OBLIGATION_DOMAINS)[number];

export interface ExternalAuthorityRecord {
  source_id: string;
  title: string;
  issuing_body: string;
  source_type: SourceAuthorityType;
  citation: string;
  source_url: string;
  source_version: string;
  source_effective_date: string;
  publication_date: string;
  verified_on: string;
  verification_method: string;
  jurisdiction: Jurisdiction;
  source_status: SourceStatus;
  lifecycle: SourceLifecycle;
  section_locators: string[];
  source_statement: string;
  reproduction_boundary: string;
  supersedes: string[];
  superseded_by: string | null;
  notes: string;
}

export interface ObligationRecord {
  obligation_id: string;
  domain: ObligationDomain;
  title: string;
  source_id: string;
  source_authority: string;
  source_type: SourceAuthorityType;
  citation: string;
  source_url: string;
  source_version: string;
  source_effective_date: string;
  verified_on: string;
  jurisdiction: Jurisdiction;
  applicability_state: ObligationApplicability;
  applicability_trigger: string;
  current_phase_applicability: string;
  future_phase_applicability: string;
  subject: string;
  obligation_summary: string;
  /** Strictly what the source says. Never interpretation. */
  source_statement_boundary: string;
  /** Strictly SSLS reading. Never presented as source text. */
  ssls_interpretation: string;
  required_control: string;
  current_control: string;
  control_family: ControlFamily;
  control_status: ControlStatus;
  mapped_work_package: string;
  evidence_requirement: string;
  minimum_evidence_method: string;
  evidence_status: ObligationEvidenceStatus;
  owner_candidate: string;
  claim_implication: string;
  prohibited_claim: string;
  review_requirement: ReviewRequirement | null;
  review_trigger: string;
  review_date: string;
  supersedes: string[];
  superseded_by: string | null;
  notes: string;
}

export interface ObligationConflictRecord {
  conflict_id: string;
  title: string;
  source_ids: string[];
  description: string;
  resolution_owner: string;
  resolution_route: string;
  state: "OPEN" | "ROUTED" | "RESOLVED";
}

export interface StaleReferenceRecord {
  stale_id: string;
  project_reference: string;
  located_in: string;
  verified_current: string;
  disposition: "CORRECT" | "NARROW" | "RECLASSIFY" | "REMOVE" | "VERIFIED";
  finding_id: string | null;
  notes: string;
}

export interface DataTriggerRecord {
  data_class: string;
  current_use: boolean;
  future_candidate_use: boolean;
  sensitivity: "standard" | "elevated" | "high";
  obligation_domains: ObligationDomain[];
  prerequisite_review: string;
  minimum_necessary: string;
  retention_question: string;
  disclosure_question: string;
}

export interface ObligationBaseline {
  schema_version: string;
  generated_at: string;
  authorities: ExternalAuthorityRecord[];
  obligations: ObligationRecord[];
  conflicts: ObligationConflictRecord[];
  stale_references: StaleReferenceRecord[];
  data_triggers: DataTriggerRecord[];
}

/** Claim wording that may never be produced from this register. */
export const PROHIBITED_OBLIGATION_CLAIMS: readonly string[] = [
  "FERPA compliant",
  "COPPA compliant",
  "WCAG compliant",
  "WCAG certified",
  "ADA compliant",
  "Section 508 compliant",
  "NIST certified",
  "DESE approved",
  "VPAT certified",
  "SOC 2 certified",
  "ISO 27001 certified",
  "Massachusetts compliant",
  "fully compliant",
  "legally cleared",
];

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

export interface ValidationIssue {
  record_id: string;
  field: string;
  message: string;
}

export function validateAuthority(record: ExternalAuthorityRecord): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const fail = (field: string, message: string) =>
    issues.push({ record_id: record.source_id, field, message });

  if (!/^SRC-\d{3}$/.test(record.source_id)) fail("source_id", "must match SRC-000");
  if (!record.title.trim()) fail("title", "required");
  if (!record.issuing_body.trim()) fail("issuing_body", "required");
  if (!SOURCE_AUTHORITY_TYPES.includes(record.source_type))
    fail("source_type", "not a canonical authority type");
  if (!record.citation.trim()) fail("citation", "citation locator required");
  if (!/^https:\/\//.test(record.source_url)) fail("source_url", "official https URL required");
  if (!ISO_DATE.test(record.verified_on)) fail("verified_on", "ISO verification date required");
  if (!JURISDICTIONS.includes(record.jurisdiction)) fail("jurisdiction", "not canonical");
  if (!SOURCE_STATUSES.includes(record.source_status)) fail("source_status", "not canonical");
  if (!SOURCE_LIFECYCLES.includes(record.lifecycle)) fail("lifecycle", "not canonical");
  if (record.source_status === "VERIFIED-CURRENT") {
    if (!record.source_version.trim() || record.source_version === "UNKNOWN")
      fail("source_version", "VERIFIED-CURRENT requires a version identifier");
    if (!record.source_effective_date.trim())
      fail("source_effective_date", "VERIFIED-CURRENT requires an effective/version date");
    if (record.superseded_by)
      fail("superseded_by", "a superseded source cannot remain VERIFIED-CURRENT");
  }
  if (record.source_status === "SUPERSEDED" && !record.superseded_by)
    fail("superseded_by", "SUPERSEDED requires the superseding source");
  if (record.section_locators.length === 0) fail("section_locators", "at least one locator");
  if (!record.source_statement.trim()) fail("source_statement", "required");
  return issues;
}

export function validateObligation(
  record: ObligationRecord,
  authorityIds: ReadonlySet<string>,
): ValidationIssue[] {
  const issues: ValidationIssue[] = [];
  const fail = (field: string, message: string) =>
    issues.push({ record_id: record.obligation_id, field, message });

  if (!/^OBL-\d{3}$/.test(record.obligation_id)) fail("obligation_id", "must match OBL-000");
  if (!OBLIGATION_DOMAINS.includes(record.domain)) fail("domain", "not canonical");
  if (!authorityIds.has(record.source_id)) fail("source_id", "no matching source register entry");
  if (!record.citation.trim()) fail("citation", "required");
  if (!ISO_DATE.test(record.verified_on)) fail("verified_on", "ISO verification date required");
  if (!APPLICABILITY_STATES.includes(record.applicability_state))
    fail("applicability_state", "not canonical");
  if (!CONTROL_STATUSES.includes(record.control_status)) fail("control_status", "not canonical");
  if (!OBLIGATION_EVIDENCE_STATUSES.includes(record.evidence_status))
    fail("evidence_status", "not canonical");
  if (!CONTROL_FAMILIES.includes(record.control_family)) fail("control_family", "not canonical");
  if (!record.applicability_trigger.trim()) fail("applicability_trigger", "required");
  if (!record.source_statement_boundary.trim()) fail("source_statement_boundary", "required");
  if (!record.ssls_interpretation.trim()) fail("ssls_interpretation", "required");
  if (record.review_requirement && !REVIEW_REQUIREMENTS.includes(record.review_requirement))
    fail("review_requirement", "not canonical");
  if (!record.review_trigger.trim()) fail("review_trigger", "required");
  if (!record.review_date.trim()) fail("review_date", "review date or rule required");

  // A voluntary or market source may never be phrased as a legal requirement.
  if (!LEGALLY_BINDING_AUTHORITY_TYPES.includes(record.source_type)) {
    if (/\blegally required\b|\brequired by law\b|\bmandated by law\b/i.test(record.obligation_summary))
      fail("obligation_summary", "non-binding source described as legal requirement");
  }
  // Proposed or pending authority may never carry a present-tense obligation.
  if (record.applicability_state === "APPLIES-NOW") {
    if (!record.mapped_work_package.trim())
      fail("mapped_work_package", "APPLIES-NOW requires an owning work package or decision");
    if (record.control_status === "UNKNOWN" && !record.notes.trim())
      fail("control_status", "APPLIES-NOW with UNKNOWN control requires a recorded gap note");
  }
  for (const phrase of PROHIBITED_OBLIGATION_CLAIMS) {
    if (record.claim_implication.toLowerCase().includes(phrase.toLowerCase()))
      fail("claim_implication", `prohibited claim wording: ${phrase}`);
  }
  return issues;
}

export function isGap(record: ObligationRecord): boolean {
  return (
    record.applicability_state !== "NOT-APPLICABLE" &&
    record.applicability_state !== "REFERENCE" &&
    (record.control_status === "MISSING" ||
      record.control_status === "PARTIAL" ||
      record.control_status === "SPECIFICATION-ONLY" ||
      record.control_status === "UNKNOWN")
  );
}

export function byApplicability(
  records: readonly ObligationRecord[],
  state: ObligationApplicability,
): ObligationRecord[] {
  return records.filter((record) => record.applicability_state === state);
}

/**
 * Canonical structured projection of the program's current governed state.
 *
 * This module defines the SHAPE only. The record itself lives in
 * `src/fixtures/program.ts` and is the single in-application source for gate
 * state, active work package, latest checkpoint, pending owner disposition,
 * and the explicitly unauthorized next stage. Route components read it; they
 * never restate any of it.
 *
 * Nothing here closes a gate, closes a work package, records a disposition, or
 * upgrades authority. Every field carries the locator of the canonical record
 * it reports, so any statement on a surface can be traced back to its source.
 */

export type GateState = "open" | "closed";
export type WorkPackageState = "active" | "closed-by-owner" | "not-authorized";
export type DispositionState = "pending" | "accepted" | "declined";

export interface SourceLocator {
  /** Canonical identifier, for example `DEC-018`, `FND-020`, `CHECKPOINT-003`. */
  recordId: string;
  /** Repository path or register locator. Never fabricated. */
  locator: string;
  /** In-application route that shows the owning register, when one exists. */
  route: string | null;
}

export interface GateStateRecord {
  gateId: string;
  name: string;
  state: GateState;
  basis: string;
  source: SourceLocator;
}

export interface WorkPackageStateRecord {
  workPackageId: string;
  title: string;
  state: WorkPackageState;
  statement: string;
  source: SourceLocator;
}

export interface CheckpointRecord {
  checkpointId: string;
  title: string;
  completedOn: string;
  /** What the cycle did, stated without closure language. */
  outcome: string;
  /** Stated plainly so a completed cycle is never read as a closed package. */
  closedNothing: string;
  source: SourceLocator;
}

export interface OwnerDispositionRecord {
  subject: string;
  state: DispositionState;
  requiredOf: string;
  /** The canonical obligation record this pending disposition is carried on. */
  obligationSource: SourceLocator;
  /** Supporting locators an owner needs before deciding. */
  supportingSources: SourceLocator[];
}

/** Commit- or checkpoint-bound verification. Never a standing global claim. */
export interface BoundVerificationRecord {
  verificationId: string;
  statement: string;
  /** Exactly what the statement covers. */
  scope: string;
  /** The checkpoint or commit the statement is bound to. */
  boundTo: string;
  source: SourceLocator;
}

export interface UnauthorizedStageRecord {
  stageId: string;
  statement: string;
  source: SourceLocator;
}

export interface ProgramStateRecord {
  stateDate: string;
  gate: GateStateRecord;
  activeWorkPackage: WorkPackageStateRecord;
  latestCheckpoint: CheckpointRecord;
  ownerDisposition: OwnerDispositionRecord;
  verifications: BoundVerificationRecord[];
  unauthorizedStages: UnauthorizedStageRecord[];
  /** What hosting the application does and does not mean. */
  publicationBoundary: string;
  /** The single next action the current posture permits the owner to take. */
  nextDefensibleOwnerAction: {
    action: string;
    why: string;
    source: SourceLocator;
  };
}

/**
 * Statements the program-state record may never make. Enforced by test.
 */
export const PROHIBITED_PROGRAM_STATE_CLAIMS = [
  "production ready",
  "district validated",
  "independently validated",
  "certified",
  "release authorized",
  "compliance conformance",
  "wp-039 is authorized",
] as const;

const ISO_DATE = /^\d{4}-\d{2}-\d{2}$/;

/**
 * Structural invariants only. Returns violation strings; empty means the record
 * is internally consistent. It asserts nothing about the truth of the state.
 */
export function validateProgramState(record: ProgramStateRecord): string[] {
  const problems: string[] = [];

  if (!ISO_DATE.test(record.stateDate)) problems.push("malformed state date");
  if (!ISO_DATE.test(record.latestCheckpoint.completedOn))
    problems.push("malformed checkpoint completion date");

  const locators: SourceLocator[] = [
    record.gate.source,
    record.activeWorkPackage.source,
    record.latestCheckpoint.source,
    record.ownerDisposition.obligationSource,
    ...record.ownerDisposition.supportingSources,
    ...record.verifications.map((entry) => entry.source),
    ...record.unauthorizedStages.map((entry) => entry.source),
    record.nextDefensibleOwnerAction.source,
  ];
  for (const locator of locators) {
    if (!locator.recordId.trim()) problems.push("a source locator has no record id");
    if (!locator.locator.trim()) problems.push(`${locator.recordId}: empty locator`);
  }

  for (const verification of record.verifications) {
    if (!verification.boundTo.trim())
      problems.push(`${verification.verificationId}: verification is not bound to a checkpoint or commit`);
    if (!verification.scope.trim())
      problems.push(`${verification.verificationId}: verification scope must be stated`);
  }

  const haystack = JSON.stringify(record).toLowerCase();
  for (const claim of PROHIBITED_PROGRAM_STATE_CLAIMS) {
    const index = haystack.indexOf(claim);
    if (index === -1) continue;
    const window = haystack.slice(Math.max(0, index - 90), index);
    if (!/(does not|never|no |not |neither )[^.]*$/.test(window))
      problems.push(`prohibited claim phrasing "${claim}" is not refused`);
  }

  return problems;
}

/**
 * Authorization and context model — CONTRACT ONLY.
 *
 * There is no authorization engine in this build, and none is needed: the
 * runtime has one authorized human and no stored personal data. What is defined
 * here is the shape a future decision would have to take, and the questions any
 * future implementation must be able to answer.
 *
 * The rejected model is "role equals access". A role is one input among seven.
 */

export const AUTHORIZATION_INPUTS = [
  "identity",
  "acting-capacity",
  "relationship",
  "purpose",
  "applicable-policy",
  "capability",
  "object-scope",
  "time",
] as const;

export type AuthorizationInput = (typeof AUTHORIZATION_INPUTS)[number];

export const AUTHORIZATION_INPUT_META: Record<
  AuthorizationInput,
  { id: AuthorizationInput; label: string; question: string; ifOmitted: string }
> = {
  identity: {
    id: "identity",
    label: "Identity",
    question: "Who is this, verifiably?",
    ifOmitted: "Nothing else can be attributed or audited.",
  },
  "acting-capacity": {
    id: "acting-capacity",
    label: "Acting capacity",
    question: "In which of their roles are they acting right now?",
    ifOmitted: "The widest capacity a person holds governs every action they take.",
  },
  relationship: {
    id: "relationship",
    label: "Relationship",
    question: "What connects them to this specific subject?",
    ifOmitted: "A role becomes a key to every record of that type.",
  },
  purpose: {
    id: "purpose",
    label: "Purpose",
    question: "What are they trying to accomplish?",
    ifOmitted: "Access cannot be limited to the minimum necessary.",
  },
  "applicable-policy": {
    id: "applicable-policy",
    label: "Applicable policy",
    question: "Which rule permits or forbids this?",
    ifOmitted: "The system cannot explain a decision it made.",
  },
  capability: {
    id: "capability",
    label: "Capability",
    question: "Is this action within a capability the organization actually holds?",
    ifOmitted: "People are authorized to do things nobody is accountable for.",
  },
  "object-scope": {
    id: "object-scope",
    label: "Object scope",
    question: "Which specific records, not which type of record?",
    ifOmitted: "Type-level access silently becomes population-level access.",
  },
  time: {
    id: "time",
    label: "Time",
    question: "Is this authority still in force?",
    ifOmitted: "Authority granted once persists after the reason for it ends.",
  },
};

export type AuthorizationOutcome = "permitted" | "refused" | "permitted-with-limits" | "undetermined";

export const AUTHORIZATION_OUTCOME_META: Record<
  AuthorizationOutcome,
  { id: AuthorizationOutcome; label: string; marker: string; meaning: string }
> = {
  permitted: { id: "permitted", label: "Permitted", marker: "[PERMIT]", meaning: "A named rule allows it, for this purpose, now." },
  refused: { id: "refused", label: "Refused", marker: "[REFUSED]", meaning: "A named rule forbids it. The reason is recorded." },
  "permitted-with-limits": { id: "permitted-with-limits", label: "Permitted with limits", marker: "[LIMITED]", meaning: "Allowed for a reduced projection or a shorter period." },
  undetermined: { id: "undetermined", label: "Undetermined", marker: "[UNDET]", meaning: "No rule addresses it. Default is deny, and the gap is a finding." },
};

/**
 * The explanation any authorization decision must be able to produce.
 * Every field answers a question a person is entitled to ask.
 */
export interface AuthorizationExplanation {
  /** "Why am I seeing this?" */
  whyVisible: string;
  /** "Who else can see this?" */
  whoElseCanSee: string;
  /** "Why can I perform this action?" */
  whyActionPermitted: string;
  /** "What rule permits it?" */
  governingPolicyId: string;
  /** "When does this authority expire?" */
  expiresAt: string | null;
  outcome: AuthorizationOutcome;
}

export interface AuthorizationRule {
  ruleId: string;
  name: string;
  statement: string;
  requiredInputs: AuthorizationInput[];
  defaultOutcome: Extract<AuthorizationOutcome, "refused" | "undetermined">;
  /** What this rule deliberately does not grant. */
  doesNotGrant: string[];
