  handoffIds: group(
    VALUE_STREAM_HANDOFFS,
    (h) => h.sourceStageId.replace(/-S\d\d$/, ""),
    (h) => h.handoffId,
  ),
  metricIds: group(VALUE_STREAM_METRICS, (m) => m.valueStreamId, (m) => m.metricId),
});

