source:
import { createFileRoute, Link } from "@tanstack/react-router";
import {
  Cell,
  PageHeader,
  RecordCard,
  RegistryTable,
  RowHeader,
  Section,
} from "@/components/governance/page";
import { AuthorityBadge } from "@/components/governance/authority-badge";
import { StateChip } from "@/components/governance/state-chip";
import { SyntheticMarker } from "@/components/governance/markers";
import {
  CapabilityFilterBar,
  CapabilityViewTabs,
  GateChip,
  IndependenceChip,
  StageChip,
  parseCapabilitySearch,
  type CapabilitySearch,
} from "@/components/governance/capability-controls";
import {
  CAPABILITY_DEPENDENCIES,
  DELIVERABLE_TYPES,
  ENTERPRISE_CAPABILITIES,
  NORMALIZATION_FINDINGS,
} from "@/fixtures";
import {
  CAPABILITY_DOMAINS,
  CAPABILITY_DOMAIN_META,
  CAPABILITY_TYPES,
  COVERAGE_MODE_LABEL,
  CURRENT_SCALE_STAGE,
  DEPENDENCY_KIND_LABEL,
  INDEPENDENCE_LABEL,
  MATURITY_LEVELS,
  MATURITY_LEVEL_LABEL,
  NORMALIZATION_KIND_LABEL,
  SCALE_STAGES,
  SCALE_STAGE_LABEL,
  TRIGGER_GATES,
  TRIGGER_GATE_META,
  type CapabilityDomainId,
  type CapabilityType,
  type IndependenceLevel,
  type MaturityLevel,
  type ScaleStage,
  type TriggerGate,
} from "@/domain";
import {
  coverageGroups,
  domainSummaries,
  filterCapabilities,
  gateGroups,
  independenceGroups,
  stageCounts,
} from "@/lib/capability-queries";

export const Route = createFileRoute("/capabilities/")({
  validateSearch: parseCapabilitySearch,
  head: () => ({
    meta: [
      { title: "Enterprise Capability Architecture v0.1 (Candidate) | SSLS" },
      {
        name: "description",
        content:
          "Candidate registry of SSLS enterprise capabilities across twelve domains, with independence rules, maturity stages, trigger gates, and dependencies.",
      },
      { property: "og:title", content: "Enterprise Capability Architecture v0.1 (Candidate) | SSLS" },
      {
        property: "og:description",
        content:
          "A governed candidate capability architecture. No record here carries implementation authority.",
      },
      { property: "og:type", content: "website" },
      { name: "twitter:card", content: "summary" },
    ],
  }),
  component: CapabilityCommandView,
});

function CapabilityCommandView() {
  const navigate = Route.useNavigate();
  const search = Route.useSearch();
  const filtered = filterCapabilities(ENTERPRISE_CAPABILITIES, search);

  const updateSearch = (next: Partial<CapabilitySearch>) => {
    void navigate({ search: (prev) => ({ ...prev, ...next }), replace: true });
  };

  return (
    <div>
      <PageHeader
        title="Enterprise Capability Architecture (Candidate)"
        summary={`Twelve candidate domains and ${ENTERPRISE_CAPABILITIES.length} candidate capability records. A capability is a durable organizational ability, not a role, a team, a process, or a product module.`}
      >
        <div className="flex flex-wrap items-center gap-2">
          <AuthorityBadge authorityClass="research-candidate" />
          <SyntheticMarker />
          <span className="rounded-sm border border-border-strong bg-muted px-2 py-0.5 text-xs font-semibold">
            Declared scale stage: {SCALE_STAGE_LABEL[CURRENT_SCALE_STAGE]}
          </span>
        </div>
        <p className="mt-3 rounded-md border-l-4 border-border-strong bg-muted p-3 text-sm font-semibold">
          This architecture is version 0.1 and is not approved. It grants no ownership, no staffing,
          and no implementation authority. No readiness percentage, maturity score, or blended index
          is calculated anywhere in this view, because none would be defensible.
        </p>
      </PageHeader>

      <CapabilityViewTabs current={search.view} search={search} />
      <CapabilityFilterBar search={search} resultCount={filtered.length} onChange={updateSearch} />

      {search.view === "registry" ? <RegistryView capabilities={filtered} search={search} /> : null}
      {search.view === "domains" ? <DomainMapView search={search} /> : null}
      {search.view === "dependencies" ? <DependencyView search={search} /> : null}
      {search.view === "maturity" ? <MaturityView capabilities={filtered} search={search} /> : null}
      {search.view === "independence" ? <IndependenceView capabilities={filtered} search={search} /> : null}
      {search.view === "gates" ? <GateView search={search} /> : null}
      {search.view === "coverage" ? <CoverageView capabilities={filtered} search={search} /> : null}
      {search.view === "deliverables" ? <DeliverableView search={search} /> : null}
      {search.view === "normalization" ? <NormalizationView search={search} /> : null}
    </div>
  );
}

function RegistryView({
  capabilities,
  search,
}: {
  capabilities: ReturnType<typeof filterCapabilities>;
  search: CapabilitySearch;
}) {
  return (
    <Section
      id="registry"
      title="Capability registry"
      description="One row per candidate capability. Implementation status is reported separately from authority and never changes it."
    >
      {capabilities.length === 0 ? (
        <p className="rounded-md border border-border bg-surface p-4 text-sm font-semibold">
          No capability matches the current filters. Clear a filter to see records again.
        </p>
      ) : (
        <RegistryTable
          caption="Candidate enterprise capabilities with domain, owning function, independence, execution stage, authority, and implementation status"
          headers={[
            "Capability",
            "Domain",
            "Owning function (candidate)",
            "Independence",
            "Execution stage",
            "Authority",
            "Implementation status",
          ]}
        >
          {capabilities.map((capability) => (
            <tr key={capability.capabilityId}>
              <RowHeader>
                <Link
                  to="/capabilities/$capabilityId"
                  params={{ capabilityId: capability.capabilityId }}
                  search={search}
                  className="underline underline-offset-2"
                >
                  {capability.capabilityId} — {capability.name}
                </Link>
              </RowHeader>
              <Cell className="text-muted-foreground">
                {CAPABILITY_DOMAIN_META[capability.capabilityDomain].name}
              </Cell>
              <Cell>{capability.owningFunctionCandidate}</Cell>
              <Cell>
                <IndependenceChip level={capability.independence.level} />
              </Cell>
              <Cell>
                <StageChip stage={capability.stages.execution} />
              </Cell>
              <Cell>
                <AuthorityBadge authorityClass={capability.currentAuthority} />
              </Cell>
              <Cell>
                <StateChip state={capability.implementationStatus} />
              </Cell>
            </tr>
          ))}
        </RegistryTable>
      )}
    </Section>
  );
}

function DomainMapView({ search }: { search: CapabilitySearch }) {
  const summaries = domainSummaries(ENTERPRISE_CAPABILITIES);
  return (
    <Section
      id="domains"
      title="Domain map"
      description="Twelve candidate domains. Counts are counts of declared records, not measures of progress."
    >
      <div className="grid gap-4 md:grid-cols-2">
        {summaries.map((summary) => (
          <RecordCard key={summary.id}>
            <h3 className="font-display text-lg font-semibold">
              {summary.id} — {summary.name}
            </h3>
            <p className="mt-1 text-sm text-muted-foreground">{summary.purpose}</p>
            <ul className="mt-3 space-y-1 text-sm">
              <li>Candidate capabilities recorded: {summary.count}</li>
              <li>Independent review required: {summary.independenceRequired}</li>
              <li>Gated before live personal data: {summary.gatedBeforePii}</li>
            </ul>
            <p className="mt-3">
              <Link
                to="/capabilities"
                search={{ ...search, view: "registry", domain: summary.id }}
                className="text-sm font-semibold underline underline-offset-2"
              >
                Filter the registry to {summary.id}
              </Link>
            </p>
          </RecordCard>
        ))}
      </div>
    </Section>
  );
}

function DependencyView({ search }: { search: CapabilitySearch }) {
  return (
    <Section
      id="dependencies"
      title="Dependency graph (tabular)"
      description="Rendered as a table rather than a diagram so the relationships are readable with a screen reader, without color, and at 200% zoom."
    >
      <RegistryTable
        caption="Candidate dependency relationships between capabilities"
        headers={["From", "Relationship", "To", "Why this relationship exists"]}
      >
        {CAPABILITY_DEPENDENCIES.map((dependency) => (
          <tr key={`${dependency.from}-${dependency.kind}-${dependency.to}`}>
            <RowHeader>
              <Link
                to="/capabilities/$capabilityId"
                params={{ capabilityId: dependency.from }}
                search={search}
                className="underline underline-offset-2"
              >
                {dependency.from}
              </Link>
            </RowHeader>
            <Cell>{DEPENDENCY_KIND_LABEL[dependency.kind]}</Cell>
            <Cell>
              <Link
                to="/capabilities/$capabilityId"
                params={{ capabilityId: dependency.to }}
                search={search}
                className="underline underline-offset-2"
              >
                {dependency.to}
              </Link>
            </Cell>
            <Cell className="text-muted-foreground">{dependency.rationale}</Cell>
          </tr>
        ))}
      </RegistryTable>
    </Section>
  );
}

function MaturityView({
  capabilities,
  search,
}: {
  capabilities: ReturnType<typeof filterCapabilities>;
  search: CapabilitySearch;
}) {
  const counts = stageCounts(capabilities);
  return (
    <>
      <Section
        id="stage-counts"
        title="Execution stage distribution"
        description="How many filtered capabilities must be executing by each stage. A count of records, never a score."
      >
        <RegistryTable
          caption="Count of capabilities by required execution stage"
          headers={["Stage", "Meaning", "Capabilities required to be executing"]}
        >
          {SCALE_STAGES.map((stage) => (
            <tr key={stage}>
              <RowHeader>
                <StageChip stage={stage} />
              </RowHeader>
              <Cell className="text-muted-foreground">{SCALE_STAGE_LABEL[stage]}</Cell>
              <Cell>{counts[stage]}</Cell>
            </tr>
          ))}
        </RegistryTable>
      </Section>

      <Section
        id="maturity-matrix"
        title="Maturity matrix"
        description="Declared current and target maturity per capability, with the stage each obligation begins."
      >
        <RegistryTable
          caption="Capability maturity, target maturity, and stage obligations"
          headers={[
            "Capability",
            "Current maturity (declared)",
            "Target maturity",
            "Architecture by",
            "Execution by",
            "Dedicated staffing by",
            "Independent assurance by",
          ]}
        >
          {capabilities.map((capability) => (
            <tr key={capability.capabilityId}>
              <RowHeader>
                <Link
                  to="/capabilities/$capabilityId"
                  params={{ capabilityId: capability.capabilityId }}
                  search={search}
                  className="underline underline-offset-2"
                >
                  {capability.capabilityId} — {capability.shortName}
                </Link>
              </RowHeader>
              <Cell>{MATURITY_LEVEL_LABEL[capability.currentMaturity]}</Cell>
              <Cell>{MATURITY_LEVEL_LABEL[capability.targetMaturity]}</Cell>
              <Cell>{capability.stages.architecture}</Cell>
              <Cell>{capability.stages.execution}</Cell>
              <Cell>{capability.stages.dedicatedStaffing}</Cell>
              <Cell>{capability.stages.independentAssurance}</Cell>
            </tr>
          ))}
        </RegistryTable>
      </Section>
    </>
  );
}

function IndependenceView({
  capabilities,
  search,
}: {
  capabilities: ReturnType<typeof filterCapabilities>;
  search: CapabilitySearch;
}) {
  const groups = independenceGroups(capabilities);
  return (
    <Section
      id="independence"
      title="Independence and separation of duties"
      description="Where the builder of a thing may not also be the person who validates or approves it."
    >
      <div className="space-y-6">
        {(["required", "conditional", "not-required"] as const).map((level) => (
          <div key={level}>
            <h3 className="font-display text-lg font-semibold">
              {INDEPENDENCE_LABEL[level]} ({groups[level].length})
            </h3>
            {groups[level].length === 0 ? (
              <p className="mt-2 text-sm text-muted-foreground">No capability in this group.</p>
            ) : (
              <RegistryTable
                caption={`Capabilities where ${INDEPENDENCE_LABEL[level].toLowerCase()}`}
                headers={["Capability", "Separation of duties", "Trigger", "Incompatible combinations"]}
              >
                {groups[level].map((capability) => (
                  <tr key={capability.capabilityId}>
                    <RowHeader>
                      <Link
                        to="/capabilities/$capabilityId"
                        params={{ capabilityId: capability.capabilityId }}
                        search={search}
                        className="underline underline-offset-2"
                      >
                        {capability.capabilityId} — {capability.shortName}
                      </Link>
                    </RowHeader>
                    <Cell className="text-muted-foreground">
                      {capability.independence.separationOfDuties}
                    </Cell>
                    <Cell>{capability.independence.trigger ?? "Not conditional."}</Cell>
                    <Cell>
                      {capability.incompatibleCombinations.length > 0
                        ? capability.incompatibleCombinations.join("; ")
                        : "None recorded."}
                    </Cell>
                  </tr>
                ))}
              </RegistryTable>
            )}
          </div>
        ))}
      </div>
    </Section>
  );
}

function GateView({ search }: { search: CapabilitySearch }) {
  const groups = gateGroups(ENTERPRISE_CAPABILITIES);
  return (
    <Section
      id="gates"
      title="Trigger gates"
      description="Capabilities that must exist before a named threshold is crossed. Every gate below is currently uncrossed."
    >
      <div className="space-y-6">
        {groups.map(({ gate, capabilities }) => (
          <RecordCard key={gate}>
            <div className="flex flex-wrap items-center gap-2">
              <GateChip gate={gate} />
              <span className="text-sm font-semibold">
                {capabilities.length} capabilities required before this gate
              </span>
            </div>
            <p className="mt-2 text-sm text-muted-foreground">{TRIGGER_GATE_META[gate].meaning}</p>
            <p className="mt-1 text-sm font-semibold">
              Gate state: not crossed. Nothing in the current posture may pass it.
            </p>
            <ul className="mt-3 list-disc space-y-1 pl-5 text-sm">
              {capabilities.map((capability) => (
                <li key={capability.capabilityId}>
                  <Link
                    to="/capabilities/$capabilityId"
                    params={{ capabilityId: capability.capabilityId }}
                    search={search}
                    className="underline underline-offset-2"
                  >
                    {capability.capabilityId} — {capability.name}
                  </Link>
                </li>
              ))}
            </ul>
          </RecordCard>
        ))}
      </div>
    </Section>
  );
}

function CoverageView({
  capabilities,
  search: _search,
}: {
  capabilities: ReturnType<typeof filterCapabilities>;
  search: CapabilitySearch;
}) {
  const groups = coverageGroups(capabilities);
  return (
    <Section
      id="coverage"
      title="Coverage and consolidation"
      description="How a capability may legitimately be held today. Consolidation is allowed except where independence forbids it."
    >
      <RegistryTable
        caption="Coverage modes and the capabilities eligible for each"
        headers={["Coverage mode", "Eligible capabilities", "Examples"]}
      >
        {[...groups.entries()].map(([mode, list]) => (
          <tr key={mode}>
            <RowHeader>{COVERAGE_MODE_LABEL[mode]}</RowHeader>
            <Cell>{list.length}</Cell>
            <Cell className="text-muted-foreground">
              {list
                .slice(0, 4)
                .map((c) => c.capabilityId)
                .join(", ")}
              {list.length > 4 ? ", and others" : ""}
            </Cell>
          </tr>
        ))}
      </RegistryTable>
      <p className="mt-4 rounded-md border-l-4 border-border-strong bg-muted p-3 text-sm font-semibold">
        The founder operator currently covers most capabilities. That is a declared single point of
        failure, recorded in NORM-014, not a resolved arrangement.
      </p>
    </Section>
  );
}

function DeliverableView({ search: _search }: { search: CapabilitySearch }) {
  return (
    <Section
      id="deliverables"
      title="Deliverable types"
      description="The artifact shapes a capability must produce. Producing a deliverable never changes anything's authority."
    >
      <RegistryTable
        caption="Deliverable types with default authority and whether they may justify implementation"
        headers={["Deliverable type", "Answers", "Default authority", "May justify implementation", "Exists today"]}
      >
        {DELIVERABLE_TYPES.map((deliverable) => (
          <tr key={deliverable.id}>
            <RowHeader>
              <span className="block">{deliverable.id}</span>
              <span className="block font-normal">{deliverable.name}</span>
            </RowHeader>
            <Cell className="text-muted-foreground">{deliverable.answersQuestion}</Cell>
            <Cell>
              <AuthorityBadge authorityClass={deliverable.defaultAuthority} />
            </Cell>
            <Cell>{deliverable.canJustifyImplementation ? "Yes" : "No"}</Cell>
            <Cell>
              <StateChip state={deliverable.existsToday} />
            </Cell>
          </tr>
        ))}
      </RegistryTable>
    </Section>
  );
}

function NormalizationView({ search: _search }: { search: CapabilitySearch }) {
  return (
    <Section
      id="normalization"
      title="Normalization pass"
      description="Judgments made while turning a long term list into capability records. Each is a candidate resolution, not an approved one."
    >
      <div className="space-y-4">
        {NORMALIZATION_FINDINGS.map((finding) => (
          <RecordCard key={finding.id}>
            <div className="flex flex-wrap items-start justify-between gap-2">
              <h3 className="font-display text-lg font-semibold">
                {finding.id} — {NORMALIZATION_KIND_LABEL[finding.kind]}
              </h3>
              <div className="flex flex-wrap gap-2">
                <StateChip state={finding.resolutionState} />
                {finding.synthetic ? <SyntheticMarker /> : null}
              </div>
            </div>
            <p className="mt-2 text-sm">{finding.statement}</p>
            <p className="mt-2 text-sm text-muted-foreground">
              <span className="font-semibold">Terms:</span> {finding.subjects.join(", ")}
            </p>
            <p className="mt-1 text-sm text-muted-foreground">
              <span className="font-semibold">Resolved into:</span>{" "}
              {finding.resolvedInto.length > 0 ? finding.resolvedInto.join(", ") : "No record."}
            </p>
            <p className="mt-1 text-sm">
              <span className="font-semibold">This does not assert:</span> {finding.boundary}
            </p>
          </RecordCard>
        ))}
      </div>
    </Section>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import {
  Cell,
  PageHeader,
  RecordCard,
  RegistryTable,
  RowHeader,
  Section,
} from "@/components/governance/page";
import { AuthorityBadge } from "@/components/governance/authority-badge";
import { Field, SyntheticMarker, ValueList } from "@/components/governance/markers";
import { DECISIONS } from "@/fixtures";
import { DECISION_STATE_LABEL, RECORD_STATE_LABEL } from "@/domain";

export const Route = createFileRoute("/decisions")({
  head: () => ({
    meta: [
      { title: "Decisions Register | SSLS Foundation Shell" },
      {
        name: "description",
        content:
          "Accepted, pending, required, and declined decisions governing the SSLS foundation shell, with their consequences.",
      },
      { property: "og:title", content: "Decisions Register | SSLS Foundation Shell" },
      {
        property: "og:description",
        content: "What has been decided, what is still open, and what each decision commits to.",
      },
    ],
  }),
  component: DecisionsRegister,
});

function DecisionsRegister() {
  const groups = (["required", "pending", "accepted", "declined", "superseded"] as const).map(
    (state) => ({
      state,
      records: DECISIONS.filter((decision) => decision.state === state),
    }),
  );

  return (
    <div>
      <PageHeader
        title="Decisions Register"
        summary="A decision is an act, not a state that emerges from work being finished. Accepted decisions carry authority; pending and required decisions carry none until they are made."
      />

      <Section id="register" title="Register">
        <RegistryTable
          caption="Decisions with state, date, authority class, and record state"
          headers={["Decision", "State", "Decided", "Authority", "Record state"]}
        >
          {DECISIONS.map((decision) => (
            <tr key={decision.id}>
              <RowHeader>
                <span className="block">{decision.id}</span>
                <span className="block font-normal">{decision.title}</span>
              </RowHeader>
              <Cell className="font-semibold">{DECISION_STATE_LABEL[decision.state]}</Cell>
              <Cell>
                {decision.decidedOn ? `${decision.decidedOn} by ${decision.decidedBy}` : "Not decided."}
              </Cell>
              <Cell>
                <AuthorityBadge authorityClass={decision.authorityClass} />
              </Cell>
              <Cell>{RECORD_STATE_LABEL[decision.recordState]}</Cell>
            </tr>
          ))}
        </RegistryTable>
      </Section>

      {groups
        .filter((group) => group.records.length > 0)
        .map((group) => (
          <Section
            key={group.state}
            id={`group-${group.state}`}
            title={DECISION_STATE_LABEL[group.state]}
          >
            <div className="space-y-4">
              {group.records.map((decision) => (
                <RecordCard key={decision.id}>
                  <div className="flex flex-wrap items-start justify-between gap-2">
                    <h3 className="font-display text-lg font-semibold">
                      {decision.id} — {decision.title}
                    </h3>
                    <div className="flex flex-wrap gap-2">
                      <AuthorityBadge authorityClass={decision.authorityClass} />
                      {decision.synthetic ? <SyntheticMarker /> : null}
                    </div>
                  </div>
                  <dl className="mt-2 grid gap-x-6 sm:grid-cols-2">
                    <Field label="State">{DECISION_STATE_LABEL[decision.state]}</Field>
                    <Field label="Decided">
                      {decision.decidedOn
                        ? `${decision.decidedOn} by ${decision.decidedBy}`
                        : "Not decided."}
                    </Field>
                    <Field label="Context">{decision.context}</Field>
                    <Field label="Decision">{decision.decision}</Field>
                    <Field label="Consequences">
                      <ValueList items={decision.consequences} />
                    </Field>
                    <Field label="Related artifacts">
                      <ValueList items={decision.relatedArtifacts} />
                    </Field>
                    <Field label="Supersedes">
                      <ValueList items={decision.supersedes} empty="Nothing." />
                    </Field>
                    <Field label="Superseded by">{decision.supersededBy ?? "Not superseded."}</Field>
                  </dl>
                </RecordCard>
              ))}
            </div>
          </Section>
        ))}
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import {
  Cell,
  PageHeader,
  RecordCard,
  RegistryTable,
  RowHeader,
  Section,
} from "@/components/governance/page";
import { StateChip } from "@/components/governance/state-chip";
import { Field, SyntheticMarker, ValueList } from "@/components/governance/markers";
import { FINDINGS } from "@/fixtures";
import { FINDING_SEVERITY_LABEL } from "@/domain";

export const Route = createFileRoute("/findings")({
  head: () => ({
    meta: [
      { title: "Findings Register | SSLS Foundation Shell" },
      {
        name: "description",
        content:
          "Recorded ambiguities, conflicts, and gaps in the SSLS foundation, including what each finding does not assert.",
      },
      { property: "og:title", content: "Findings Register | SSLS Foundation Shell" },
      {
        property: "og:description",
        content: "Open governance and structural findings with their resolution state.",
      },
    ],
  }),
  component: FindingsRegister,
});

function FindingsRegister() {
  return (
    <div>
      <PageHeader
        title="Findings Register"
        summary="Problems are recorded rather than resolved quietly. Each finding states what it asserts, what it does not assert, and whether it is waiting on a decision."
      />

      <Section id="register" title="Register">
        <RegistryTable
          caption="Findings with severity, affected layers, resolution state, and required decision"
          headers={["Finding", "Severity", "Affected layers", "Resolution state", "Required decision"]}
        >
          {FINDINGS.map((finding) => (
            <tr key={finding.id}>
              <RowHeader>
                <span className="block">{finding.id}</span>
                <span className="block font-normal">{finding.title}</span>
              </RowHeader>
              <Cell>{FINDING_SEVERITY_LABEL[finding.severity]}</Cell>
              <Cell>{finding.affectedLayers.join(", ")}</Cell>
              <Cell>
                <StateChip state={finding.resolutionState} describe />
              </Cell>
              <Cell>{finding.requiredDecision ?? "None recorded."}</Cell>
            </tr>
          ))}
        </RegistryTable>
      </Section>

      <Section id="records" title="Finding records">
        <div className="space-y-4">
          {FINDINGS.map((finding) => (
            <RecordCard key={finding.id}>
              <div className="flex flex-wrap items-start justify-between gap-2">
                <h3 className="font-display text-lg font-semibold">
                  {finding.id} — {finding.title}
                </h3>
                <div className="flex flex-wrap gap-2">
                  <StateChip state={finding.resolutionState} />
                  {finding.synthetic ? <SyntheticMarker /> : null}
                </div>
              </div>
              <dl className="mt-2 grid gap-x-6 sm:grid-cols-2">
                <Field label="Severity">{FINDING_SEVERITY_LABEL[finding.severity]}</Field>
                <Field label="Raised">
                  {finding.raisedOn} by {finding.raisedBy}
                </Field>
                <Field label="Affected layers">
                  <ValueList items={finding.affectedLayers} />
                </Field>
                <Field label="Required decision">{finding.requiredDecision ?? "None."}</Field>
                <Field label="Description">{finding.description}</Field>
                <Field label="What this finding does not assert">{finding.boundary}</Field>
                <Field label="Evidence references">
                  <ValueList items={finding.evidenceReferences} empty="No evidence recorded." />
                </Field>
              </dl>
            </RecordCard>
          ))}
        </div>
      </Section>
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
import { PageHeader, RecordCard, Section, RegistryTable, Cell, RowHeader } from "@/components/governance/page";
import { AuthorityBadge } from "@/components/governance/authority-badge";
import { StateChip } from "@/components/governance/state-chip";
import { SyntheticMarker } from "@/components/governance/markers";
import { FOUNDATION_LAYERS, artifactsForLayer } from "@/fixtures";
import { RECORD_STATE_LABEL } from "@/domain";

export const Route = createFileRoute("/foundation-map")({
  head: () => ({
    meta: [
      { title: "Foundation Map | SSLS Foundation Shell" },
      {
        name: "description",
        content:
          "The layered SSLS foundation from North Star through implementation, with the authority state of every artifact attached to each layer.",
      },
      { property: "og:title", content: "Foundation Map | SSLS Foundation Shell" },
      {
        property: "og:description",
        content: "Inspect each foundation layer and the artifacts recorded against it.",
      },
    ],
  }),
  component: FoundationMap,
});

const FLOW = [
  "North Star",
  "Doctrine",
  "Governance and cross-cutting standards",
  "Enterprise capabilities",
  "Enterprise operating model",
  "Product and domain architecture",
  "Knowledge and educational systems",
  "Technical and governance platform",
  "Implementation, validation, release, operations",
];

function FoundationMap() {
  return (
    <div>
      <PageHeader
        title="Foundation Map"
        summary="The foundation reads downward from the North Star to operations. A layer below does not gain authority from a layer above; each artifact carries its own declared authority."
      />

      <Section
        id="flow"
        title="Descent from North Star to operations"
        description="Read top to bottom. Each step names what the next step must answer to."
      >
        <ol className="space-y-2">
          {FLOW.map((step, index) => (
            <li
              key={step}
              className="flex items-start gap-3 rounded-md border border-border bg-surface p-3"
            >
              <span
                aria-hidden="true"
                className="font-mono text-xs font-bold text-muted-foreground"
              >
                {String(index + 1).padStart(2, "0")}
              </span>
              <span className="font-display text-sm font-semibold">{step}</span>
            </li>
          ))}
        </ol>
      </Section>

      <Section
        id="layer-table"
        title="Layer table"
        description="Labels L0 through L7 are preserved exactly as issued. The count discrepancy is recorded as finding FND-001 rather than renumbered."
      >
        <RegistryTable
          caption="Foundation layers with declared state, authority, and promotion requirement"
          headers={["Layer", "Name", "Declared state", "Declared authority", "Promotion requirement"]}
        >
          {FOUNDATION_LAYERS.map((layer) => (
            <tr key={layer.id}>
              <RowHeader>{layer.id}</RowHeader>
              <Cell>{layer.name}</Cell>
              <Cell>{RECORD_STATE_LABEL[layer.declaredState]}</Cell>
              <Cell>
                <AuthorityBadge authorityClass={layer.declaredAuthority} />
              </Cell>
              <Cell className="text-muted-foreground">{layer.promotionRequirement}</Cell>
            </tr>
          ))}
        </RegistryTable>
      </Section>

      <Section
        id="layer-detail"
        title="Artifacts attached to each layer"
        description="An artifact may touch several layers. Its authority does not change with the layer it is viewed from."
      >
        <div className="space-y-4">
          {FOUNDATION_LAYERS.map((layer) => {
            const artifacts = artifactsForLayer(layer.id);
            return (
              <RecordCard key={layer.id}>
                <div className="flex flex-wrap items-start justify-between gap-2">
                  <h3 className="font-display text-lg font-semibold">
                    {layer.id} — {layer.name}
                  </h3>
                  <AuthorityBadge authorityClass={layer.declaredAuthority} />
                </div>
                <p className="measure mt-2 text-sm text-muted-foreground">{layer.purpose}</p>

                {artifacts.length === 0 ? (
                  <p className="mt-3 text-sm">
                    <StateChip state="unknown" /> No artifacts recorded against this layer.
                  </p>
                ) : (
                  <ul className="mt-3 space-y-2">
                    {artifacts.map((artifact) => (
                      <li
                        key={artifact.id}
                        className="flex flex-wrap items-center gap-2 border-t border-border pt-2 text-sm"
                      >
                        <span className="font-semibold">{artifact.id}</span>
                        <span>{artifact.title}</span>
                        <AuthorityBadge authorityClass={artifact.authorityClass} />
                        <StateChip state={artifact.evidenceBasis} />
                        {artifact.synthetic ? <SyntheticMarker /> : null}
                      </li>
                    ))}
                  </ul>
                )}
              </RecordCard>
            );
          })}
        </div>
      </Section>
    </div>
  );
}

import { createFileRoute } from "@tanstack/react-router";
