  }),
  component: SearchPage,
});

function SearchPage() {
  const [term, setTerm] = useState("");
  const outcome = runSearch({
    term,
    capacityId: ACTIVE_CAPACITY.capacityId,
    domain: "all",
    authority: "all",
    status: "all",
    freshness: "all",
    tense: "all",
  });
  const hint =
    outcome.surfaceStateHint === "normal"
      ? SURFACE_STATE_META.normal
