              <tr key={`${record.domain}-${record.recordId}`}>
                <RowHeader>
                  <Link to={record.route}>{record.title}</Link>
                  <span className="mt-1 block text-xs font-normal text-muted-foreground">
                    {record.snippet}
                  </span>
