                <Cell>{SEARCH_DOMAIN_LABEL[record.domain]}</Cell>
                <Cell>{record.authorityClass}</Cell>
                <Cell>{record.status}</Cell>
                <Cell>{record.freshness}</Cell>
                <Cell>{record.provenance}</Cell>
              </tr>
